import { createReadStream, existsSync } from 'node:fs'
import { stat } from 'node:fs/promises'
import { extname, join, normalize, resolve } from 'node:path'
import { fileURLToPath, URL } from 'node:url'

import { defineConfig, type Plugin } from 'vite'

const generatedTypes: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
}

// The reading pages are generated by `npm run build:docs` into these dirs and are not part of
// the dev server's module graph, so serve them from there under their routes in dev only.
// Once built, the assembler copies them into the Pages output and this middleware is not used.
const generatedDocs = [
  {
    route: '/api',
    label: 'API reference',
    dir: fileURLToPath(new URL('./.api-docs', import.meta.url)),
  },
  {
    route: '/react',
    label: 'React page',
    dir: fileURLToPath(new URL('./.react-docs', import.meta.url)),
  },
]

const docsPages: Plugin = {
  name: 'hugframe-generated-docs',
  apply: 'serve',
  configureServer(server) {
    server.middlewares.use(async (request, response, next) => {
      const pathname = new URL(request.url ?? '/', 'http://localhost').pathname
      const doc = generatedDocs.find(
        (page) => pathname === page.route || pathname.startsWith(`${page.route}/`),
      )
      if (!doc) return next()

      if (pathname === doc.route) {
        response.writeHead(301, { location: `${doc.route}/` }).end()
        return
      }

      if (!existsSync(doc.dir)) {
        response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' })
        response.end(
          `The ${doc.label} is not built yet. Run \`npm run build:docs\` to generate ${doc.route}/, then reload it.\n`,
        )
        return
      }

      let relative = normalize(pathname.slice(doc.route.length)).replace(/^\/+/, '')
      if (relative === '' || relative.endsWith('/')) relative = join(relative, 'index.html')

      const file = resolve(doc.dir, relative)
      if (!file.startsWith(doc.dir)) {
        response.writeHead(403).end('forbidden')
        return
      }

      try {
        const info = await stat(file)
        if (!info.isFile()) throw new Error('not a file')
        response.writeHead(200, {
          'content-type': generatedTypes[extname(file)] ?? 'application/octet-stream',
          'content-length': info.size,
          'cache-control': 'no-store',
        })
        createReadStream(file).pipe(response)
      } catch {
        response
          .writeHead(404, { 'content-type': 'text/plain; charset=utf-8' })
          .end(`not found: ${pathname}`)
      }
    })
  },
}

export default defineConfig({
  // The site is a multi-page build. Without this an unknown path silently falls back to
  // index.html, whose relative links then resolve against that stray URL and append a
  // segment on every click.
  appType: 'mpa',
  server: {
    port: 5176,
  },
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
    },
  },
  build: {
    rollupOptions: {
      input: {
        index: fileURLToPath(new URL('./index.html', import.meta.url)),
        child: fileURLToPath(new URL('./child.html', import.meta.url)),
        playground: fileURLToPath(new URL('./playground/index.html', import.meta.url)),
      },
    },
  },
  plugins: [docsPages],
})
